'use client'

import * as THREE from 'three'
import { useThree } from '@react-three/fiber'
import { useEffect } from 'react'

export function Sky() {
  const { scene } = useThree()

  useEffect(() => {
    // Gradient sky from light blue at top to warm peach at bottom
    const canvas = document.createElement('canvas')
    canvas.width = 2
    canvas.height = 256
    const ctx = canvas.getContext('2d')!

    const gradient = ctx.createLinearGradient(0, 0, 0, 256)
    gradient.addColorStop(0, '#87CEEB')    // Light sky blue at top
    gradient.addColorStop(0.4, '#B4E0F0')  // Softer blue
    gradient.addColorStop(0.7, '#F0E6D3')  // Warm cream
    gradient.addColorStop(1, '#FFE4B5')    // Peach at bottom

    ctx.fillStyle = gradient
    ctx.fillRect(0, 0, 2, 256)

    const texture = new THREE.CanvasTexture(canvas)
    texture.mapping = THREE.EquirectangularReflectionMapping
    scene.background = texture

    return () => {
      texture.dispose()
    }
  }, [scene])

  return null
}
